using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.U2D.Sprites;
public static class JewelUiImport {
 public static string Run() {
 const string path="Assets/Art/PinkJewel/JewelUI.png";
 AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);
 var importer=(TextureImporter)AssetImporter.GetAtPath(path);
 importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Multiple;
 importer.spritePixelsPerUnit=32f;importer.filterMode=FilterMode.Point;
 importer.textureCompression=TextureImporterCompression.Uncompressed;importer.mipmapEnabled=false;
 importer.alphaIsTransparency=true;importer.wrapMode=TextureWrapMode.Clamp;
 importer.npotScale=TextureImporterNPOTScale.None;importer.maxTextureSize=128;
 importer.SaveAndReimport();
 var factories=new SpriteDataProviderFactories();factories.Init();
 var provider=factories.GetSpriteEditorDataProviderFromObject(importer);
 if(provider==null)throw new Exception("Sprite data provider unavailable; slicing aborted");
 provider.InitSpriteEditorDataProvider();
 var edits=provider.GetDataProvider<ISpriteFrameEditCapability>();
 if(edits==null)throw new Exception("Sprite edit capability unavailable; slicing aborted");
 var capability=edits.GetEditCapability();
 foreach(var required in new[]{EEditCapability.CreateAndDeleteSprite,EEditCapability.EditSpriteName,EEditCapability.EditSpriteRect,EEditCapability.EditPivot})
 if(!capability.HasCapability(required))throw new Exception("Unsupported sprite operation: "+required);
 var ids=provider.GetDataProvider<ISpriteNameFileIdDataProvider>();
 if(ids==null)throw new Exception("Name/file ID provider unavailable; slicing aborted");
 var existing=provider.GetSpriteRects();
 string[] names={"JewelCollected","JewelEmpty"};
 var rects=names.Select((name,i)=>new SpriteRect{name=name,rect=new Rect(i==0?16:44,8,18,29),pivot=new Vector2(0.5f,0.5f),alignment=SpriteAlignment.Center,spriteID=existing.Any(r=>r.name==name)?existing.First(r=>r.name==name).spriteID:GUID.Generate()}).ToArray();
 provider.SetSpriteRects(rects);ids.SetNameFileIdPairs(rects.Select(r=>new SpriteNameFileIdPair(r.name,r.spriteID)));
 provider.Apply();importer.SaveAndReimport();
 return string.Join("; ",AssetDatabase.LoadAllAssetsAtPath(path).OfType<Sprite>().Select(s=>s.name+" "+s.rect));
 }
}
